// Каждому агенту — свой вопрос. Один и тот же запрос дал бы
// одинаковые ответы, а смысл в том, что роли нужны разные сводки.
return [
  { json: { role: 'student', question: 'Какие сроки и дедлайны действуют на этой неделе? Ответь списком.' } },
  { json: { role: 'teacher', question: 'Что важного в организационных материалах кафедры? Ответь списком.' } },
  { json: { role: 'admin',   question: 'Какие сроки рассмотрения заявлений действуют? Ответь списком.' } },
];

// Собираем один дайджест из трёх ответов.
// Источники показываем явно — это принцип Navi: видно, откуда факт.
const ROLE_RU = { student: 'Студентам', teacher: 'Преподавателям', admin: 'Администрации' };
const items = $input.all();

const blocks = items.map((i, idx) => {
  const answer = i.json.reply || '—';
  const srcs = (i.json.sources || []).map((s) => '· ' + s.title).join('\n');
  const role = $('Вопрос под каждую роль').all()[idx]?.json?.role || '';
  return [
    '*' + (ROLE_RU[role] || role) + '*',
    answer,
    srcs ? '\n_Источники:_\n' + srcs : '',
  ].join('\n');
});

const text = ['📅 *Дайджест Navi на сегодня*', '', blocks.join('\n\n———\n\n')].join('\n');
return [{ json: { text } }];
